-- 水質検査箇所マスタ.カラム情報に連携コード1, 連携コード2を追加
UPDATE sys_master_define
SET column_info = '{"fields": [{"type": "number", "alias": "code", "title": "水質検査箇所コード", "format": null, "hidden": "true", "editable": "false", "validation": {"max": null, "min": null, "required": "true", "maxlength": null}, "physical_name": "survey_point_cd"}, {"type": "string", "alias": "name", "title": "水質検査箇所名", "format": null, "hidden": "false", "locked": "true", "editable": "true", "validation": {"max": null, "min": null, "required": "true", "maxlength": "64"}, "physical_name": "point_name"}, {"type": "combo2", "alias": null, "title": "対象装置", "format": null, "hidden": "false", "editable": "true", "validation": {"max": null, "min": null, "required": false, "maxlength": null}, "physical_name": "machine_no"}, {"type": "combo2", "alias": null, "title": "水質調査種別", "format": null, "hidden": "false", "editable": "true", "validation": {"max": null, "min": null, "required": true, "maxlength": null}, "physical_name": "survey_type_cd"},  {"type": "string", "alias": null, "title": "連携コード1", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_1"}, {"type": "string", "alias": null, "title": "連携コード2", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_2"}, {"type": "disp", "alias": null, "title": "削除", "format": null, "hidden": "false", "editable": "true", "validation": {"max": null, "min": null, "required": null, "maxlength": null}, "physical_name": "is_disp"}, {"type": "del", "alias": null, "title": "削除フラグ", "format": null, "hidden": "true", "editable": "true", "validation": {"max": null, "min": null, "required": null, "maxlength": null}, "physical_name": "is_del"}]}',
    up_date = CURRENT_TIMESTAMP
WHERE master_physical_name = 'mst_water_survey_point';
